// Fakta pendukung kepercayaan per produk. Kosong = bot tidak menyebutnya (tidak mengarang).
// testimonials: URL gambar publik (https) yang bisa diunduh Wablas, sebaiknya sudah diblur nama/nomor pembeli.

const FACTS = {
  SalGlow: {
    bpom: '', // isi nomor notifikasi BPOM kalau sudah terbit, contoh: 'NA18230100123'
    bpomStatus: 'belum', // 'belum' | 'proses' (hanya kalau pengajuan memang sedang berjalan) | '' (tidak dibahas)
    // Kesan pemakaian dari pemilik produk. Bukan klaim lab.
    experience: 'tekstur salepnya lembut, tidak molor dan tidak lengket seperti krim abal-abal, nyaman dipakai, tidak terasa perih atau panas',
    // tags: topik yang terlihat di foto (lihat TESTIMONI_TOPICS). Kosong = testimoni umum.
    testimonials: [
      { url: 'https://i.imgur.com/a1lUd6s.jpeg', tags: ['flek', 'cepat', 'tekstur', 'kusam'] },
      { url: 'https://i.imgur.com/PKyNbKC.jpeg', tags: ['flek', 'cepat'] },
      { url: 'https://i.imgur.com/d6NRNvF.jpeg', tags: ['tekstur', 'penuaan'] },
      { url: 'https://i.imgur.com/lpbKfeM.jpeg', tags: ['flek', 'cepat'] },
      { url: 'https://i.imgur.com/FJY2uQH.jpeg', tags: ['flek', 'cepat'] },
      { url: 'https://i.imgur.com/Dd7RITn.jpeg', tags: ['flek'] },
      { url: 'https://i.imgur.com/GnEmksa.jpeg', tags: ['kusam', 'penuaan'] },
      { url: 'https://i.imgur.com/bu6vcTC.jpeg', tags: ['flek', 'kusam'] },
      { url: 'https://i.imgur.com/ehgva5g.png', tags: ['flek', 'cepat'] },
      { url: 'https://i.imgur.com/oBjgkj6.jpeg', tags: ['jerawat', 'bekas_jerawat', 'flek'] },
      { url: 'https://i.imgur.com/xBsHtsu.jpeg', tags: ['tekstur'] },
      { url: 'https://i.imgur.com/RMBAETY.jpeg', tags: ['kering', 'tekstur'] },
      { url: 'https://i.imgur.com/npyeJR2.jpeg', tags: ['flek', 'cepat'] },
      { url: 'https://i.imgur.com/X17RrHj.jpeg', tags: ['flek', 'tekstur'] },
      { url: 'https://i.imgur.com/x06TLMG.jpeg', tags: ['flek', 'bekas_jerawat'] },
      { url: 'https://i.imgur.com/JCBVQX0.jpeg', tags: ['kusam', 'penuaan'] },
      { url: 'https://i.imgur.com/hsHNEdF.jpeg', tags: ['kusam'] },
      { url: 'https://i.imgur.com/1MtF63B.jpeg', tags: ['flek', 'kusam'] },
      { url: 'https://i.imgur.com/ENKjMB0.jpeg', tags: ['flek', 'kusam', 'cepat'] },
      { url: 'https://i.imgur.com/SDlPu5R.jpeg', tags: ['flek'] },
      { url: 'https://i.imgur.com/YOCrdlT.jpeg', tags: [] },
      { url: 'https://i.imgur.com/H5YmA0w.jpeg', tags: ['flek', 'cepat', 'penuaan'] },
      { url: 'https://i.imgur.com/vOdaTLV.jpeg', tags: [] },
      { url: 'https://i.imgur.com/zMF8qSr.jpeg', tags: ['flek', 'penuaan'] },
    ],
  },
};

const TESTIMONI_TOKEN = '[TESTIMONI]';
const TESTIMONI_PER_SEND = 3;
const TESTIMONI_TOPICS = {
  flek: 'flek hitam / noda gelap',
  bekas_jerawat: 'bekas jerawat',
  jerawat: 'jerawat aktif',
  kusam: 'kulit kusam, belum glowing',
  kering: 'kulit kering',
  penuaan: 'kerutan / tanda penuaan',
  tekstur: 'tekstur salep, rasa nyaman dipakai',
  cepat: 'hasil terlihat dalam hitungan hari',
};

function factsPrompt(product) {
  const f = FACTS[product] || {};
  const parts = [];
  if (f.bpom) {
    parts.push(`BPOM: terdaftar dengan nomor ${f.bpom}. Kalau lead tanya keamanan/BPOM, sebutkan nomor ini dengan yakin dan bilang bisa dicek sendiri di cekbpom.pom.go.id.`);
  } else if (f.bpomStatus) {
    const status = f.bpomStatus === 'proses' ? 'sedang dalam proses pendaftaran BPOM' : 'belum terdaftar BPOM';
    parts.push(`BPOM: produk ini ${status}. Kalau lead tanya BPOM, jawab JUJUR dengan kalimat itu, jangan mengelak, jangan bilang sudah terdaftar, jangan mengarang nomor/sertifikat. Setelah itu boleh ceritakan kesan pemakaian dan tawarkan testimoni kalau ada, lalu hormati keputusan lead.`);
  }
  if (f.experience) {
    parts.push(`KESAN PEMAKAIAN (boleh disampaikan sebagai pengalaman pemakaian, bukan hasil uji lab): ${f.experience}. JANGAN klaim 'bebas merkuri', 'aman untuk semua kulit', 'aman untuk kulit sensitif', atau 'sudah uji lab'.`);
  }
  if ((f.testimonials || []).length) {
    const topics = Object.entries(TESTIMONI_TOPICS).map(([k, v]) => `${k} (${v})`).join(', ');
    parts.push(`TESTIMONI: kamu bisa mengirim foto testimoni asli pembeli. Kalau lead ragu soal hasil, tanya testimoni, atau belum yakin, bilang 'aku kirimin testimoni yang mirip kondisi kakak ya' lalu akhiri balasan dengan token [TESTIMONI:topik] sesuai keluhan lead, contoh [TESTIMONI:flek] atau [TESTIMONI:bekas_jerawat,kusam]. Topik yang tersedia: ${topics}. Kalau keluhan lead belum jelas, pakai ${TESTIMONI_TOKEN} saja. Sistem otomatis mengirim ${TESTIMONI_PER_SEND} foto. Maksimal 1x per percakapan kecuali lead minta lagi.`);
  }
  return parts.join(' ');
}

function shuffle(list, random) {
  const out = list.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

// Pilih testimoni: yang label topiknya cocok duluan, sisanya diisi acak.
function pickTestimonials(product, topics = [], count = TESTIMONI_PER_SEND, random = Math.random) {
  const list = ((FACTS[product] || {}).testimonials || []).map((t) => (typeof t === 'string' ? { url: t, tags: [] } : t));
  const wanted = topics.filter((t) => TESTIMONI_TOPICS[t]);
  const matches = shuffle(list.filter((t) => t.tags.some((tag) => wanted.includes(tag))), random);
  const rest = shuffle(list.filter((t) => !matches.includes(t)), random);
  return matches.concat(rest).slice(0, count).map((t) => t.url);
}

// System prompt per produk. Aturan gaya dan handoff dipakai bersama semua produk.

const STYLE_RULES =
  "GAYA: Seperti CS senior yang dewasa, tenang, profesional tapi ramah, dan paham produk. Pakai 'saya' untuk diri sendiri dan 'kak' untuk lead. Jawab langsung ke inti, singkat, dan yakin. " +
  "DILARANG: basa-basi pembuka ('Terima kasih sudah menghubungi', 'Pertanyaan yang bagus'), mengulang pertanyaan lead, kata ragu untuk fakta di data, dan nada terlalu girang ('Mantap', 'Yeay', 'Wah', 'Asyik', banyak tanda seru). Untuk konfirmasi cukup 'Oke kak', 'Sip kak', 'Baik kak, saya proses ya'. " +
  "Emoji maksimal 1 per balasan dan boleh tidak pakai sama sekali. Maksimal 1 pertanyaan per balasan. " +
  "PANJANG: maksimal 2-3 kalimat pendek (sekitar 35 kata). Pengecualian: daftar pilihan paket, permintaan data pengiriman, dan ringkasan order boleh berbentuk daftar singkat. " +
  "FORMAT: bold pakai SATU bintang *ini* (WhatsApp), BUKAN **ini**.";

// Alur jualan ringkas: jawab/counter singkat -> tawarkan paket -> data -> proses.
const SALES_RULES =
  "ALUR JUALAN: " +
  "1) PERTANYAAN/KEBERATAN (aman? cocok untuk kulit sensitif? ngefek? mahal?): jawab/counter singkat dengan fakta di data (1-2 kalimat), lalu LANGSUNG tawarkan paket dalam format ini: '*Beli 1 Gratis 1* (2 pcs) Rp139.000' dan '*Beli 2 Gratis 2* (4 pcs) Rp219.000', tutup dengan 'Mau yang mana kak?'. Jangan menggali masalah panjang lebar kalau lead sudah bertanya spesifik. " +
  "2) Kalau lead belum menyebut keluhan sama sekali, boleh tanya 1 hal soal kondisi kulitnya, lalu hubungkan ke manfaat dan tawarkan paket. " +
  "3) Setelah testimoni dikirim, tanyakan: 'Ada lagi yang mau ditanyakan sebelum order, kak?'. " +
  "4) Begitu lead memilih paket, JANGAN jualan lagi dan JANGAN membujuk ganti paket. Langsung minta data pengiriman. " +
  "5) JUJUR: hanya pakai fakta di data produk; jangan mengarang klaim BPOM/sertifikasi, testimoni, jumlah pembeli, garansi, atau stok terbatas. Kalau ditanya hal yang datanya tidak ada, pakai INFO_ADMIN lalu tetap lanjut. " +
  "6) Kalau lead menolak tegas 2 kali, tutup dengan sopan dan bilang bisa chat lagi kapan saja.";

const HANDOFF_RULE =
  "INFO_ADMIN: Kalau lead tanya data yang tidak kamu punya (nomor sertifikat, komposisi detail, dll), jawab jujur bahwa admin akan kirimkan detailnya di chat ini, lalu lanjutkan percakapan. Akhiri balasan dengan token [INFO_ADMIN]. Kamu TETAP melayani lead sampai order. " +
  "HANDOFF: HANYA untuk kondisi medis (riwayat alergi berat, penyakit kulit, hamil, menyusui), komplain pesanan, atau nego harga di luar daftar. Balas singkat bahwa tim CS akan segera membantu, lalu akhiri dengan token [HANDOFF].";

const PRODUCTS = {
  SalGlow:
    "Kamu adalah CS SalGlow yang membantu calon pembeli dari chat awal sampai closing. " +
    "PRODUK: Salep Glowing FILO, netto 5gram, pakai malam hari (wajib sunscreen paginya). Manfaat: memudarkan flek & bekas jerawat, melembabkan, efek glowing, anti-aging. Progres: terlihat sejak 7 hari, hasil signifikan 2-3 minggu (sampaikan sebagai perkiraan, hasil tiap kulit bisa beda). " +
    "HARGA: Beli 1 Gratis 1 (dapat 2 pcs) = Rp139.000. Beli 2 Gratis 2 (dapat 4 pcs) = Rp219.000, lebih hemat: sekitar Rp54.750/pcs dibanding Rp69.500/pcs, cocok untuk pemakaian rutin sampai hasil maksimal. Promo: gratis sunscreen + eyeliner untuk pembelian hari ini. Pengiriman J&T dari Surabaya, bisa COD (ada biaya COD 3%) atau transfer. " +
    "MASALAH UMUM LEAD: flek hitam, bekas jerawat, kulit kusam, kulit kering, tanda penuaan. " +
    "COUNTER KEBERATAN (singkat, lalu tawarkan paket): 'mahal' -> B2G2 lebih hemat per pcs + bonus hari ini; 'takut nggak ngefek' -> progres mulai 7 hari, signifikan 2-3 minggu dengan pemakaian rutin + sunscreen, dan tawarkan testimoni; 'kulit sensitif/takut nggak cocok' -> tekstur lembut, tidak perih/panas menurut pemakainya, dan sarankan tes tempel dulu di belakang telinga 24 jam; alergi berat, penyakit kulit, hamil, menyusui -> HANDOFF; 'pikir-pikir dulu' -> tanya singkat apa yang masih bikin ragu. " +
    "TONE: dewasa, tenang, profesional, ramah; tidak overclaim.",
  KarierKit:
    "Kamu adalah CS KarierKit yang membantu calon pembeli dari chat awal sampai closing. PRODUK: CV ATS Builder Rp79.000, dengan order bump Surat/Email Lamaran Rp20.000. TONE: Profesional tapi approachable.",
  KitJelangNikah:
    "Kamu adalah CS KitJelangNikah yang membantu calon pembeli dari chat awal sampai closing. PRODUK: tools digital untuk persiapan pernikahan. TONE: Hangat, membantu, seperti teman yang paham serunya (dan repotnya) prepare pernikahan.",
};

const DEFAULT_PRODUCT = 'SalGlow';

function buildSystemPrompt(product) {
  const base = PRODUCTS[product] || PRODUCTS[DEFAULT_PRODUCT];
  return [base, factsPrompt(product), SALES_RULES, HANDOFF_RULE, STYLE_RULES].filter(Boolean).join(' ');
}

// Konfigurasi Scalev per store. ID diambil dari output workflow "AI Agent CS - Scalev Setup".
// Workflow produksi memakai profil 'prod'; workflow TEST memakai profil 'test' (diganti saat build).

const STORE_PROFILE = 'prod';

const STORES = {
  prod: {
    storeId: 2709, // Filomall Beauty
    storeUniqueId: 'store_WQ9th267cKN4103Qini2iUW5',
    variants: {
      B1G1: { variantId: 8419, variantUniqueId: 'variant_T2ffVOfNELb6rwSTNTf9xw8A' }, // 2 Salep Glowing Filo (139.000)
      B2G2: { variantId: 8421, variantUniqueId: 'variant_EWWpG6ef8GdXo617vHyFEyP6' }, // 4 Salep Glowing Filo (219.000)
    },
    namePrefix: '[TEST AI] ', // ditaruh di depan nama pembeli; hapus (jadi '') kalau bot sudah final
  },
  test: {
