        content = { ok: false, error: `Order gagal dibuat (${msg}). Bilang tim CS akan bantu proses. [HANDOFF]` };
      }
    }
  }
  return {
    block: { type: 'tool_result', tool_use_id: state.toolUseId, content: JSON.stringify(content), is_error: !content.ok },
    order,
  };
}

