const TESTIMONI_TOKEN = '[TESTIMONI]';
const TESTIMONI_PER_SEND = 3;
const TESTIMONI_TOPICS = {
  flek: 'flek hitam / noda gelap',
  bekas_jerawat: 'bekas jerawat',
  jerawat: 'jerawat aktif',
  kusam: 'kulit kusam, belum glowing',
  kering: 'kulit kering',
  penuaan: 'kerutan / tanda penuaan',
  tekstur: 'tekstur salep, rasa nyaman dipakai',
  cepat: 'hasil terlihat dalam hitungan hari',
};

function factsPrompt(product) {
  const f = FACTS[product] || {};
  const parts = [];
  if (f.bpom) {
    parts.push(`BPOM: terdaftar dengan nomor ${f.bpom}. Kalau lead tanya keamanan/BPOM, sebutkan nomor ini dengan yakin dan bilang bisa dicek sendiri di cekbpom.pom.go.id.`);
  } else if (f.bpomStatus) {
    const status = f.bpomStatus === 'proses' ? 'sedang dalam proses pendaftaran BPOM' : 'belum terdaftar BPOM';
    parts.push(`BPOM: produk ini ${status}. Kalau lead tanya BPOM, jawab JUJUR dengan kalimat itu, jangan mengelak, jangan bilang sudah terdaftar, jangan mengarang nomor/sertifikat. Setelah itu boleh ceritakan kesan pemakaian dan tawarkan testimoni kalau ada, lalu hormati keputusan lead.`);
  }
  if (f.experience) {
    parts.push(`KESAN PEMAKAIAN (boleh disampaikan sebagai pengalaman pemakaian, bukan hasil uji lab): ${f.experience}. JANGAN klaim 'bebas merkuri', 'aman untuk semua kulit', 'aman untuk kulit sensitif', atau 'sudah uji lab'.`);
  }
  if ((f.testimonials || []).length) {
    const topics = Object.entries(TESTIMONI_TOPICS).map(([k, v]) => `${k} (${v})`).join(', ');
    parts.push(`TESTIMONI: kamu bisa mengirim foto testimoni asli pembeli. Kalau lead ragu soal hasil, tanya testimoni, atau belum yakin, bilang 'aku kirimin testimoni yang mirip kondisi kakak ya' lalu akhiri balasan dengan token [TESTIMONI:topik] sesuai keluhan lead, contoh [TESTIMONI:flek] atau [TESTIMONI:bekas_jerawat,kusam]. Topik yang tersedia: ${topics}. Kalau keluhan lead belum jelas, pakai ${TESTIMONI_TOKEN} saja. Sistem otomatis mengirim ${TESTIMONI_PER_SEND} foto. Maksimal 1x per percakapan kecuali lead minta lagi.`);
  }
  return parts.join(' ');
}

function shuffle(list, random) {
  const out = list.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

// Pilih testimoni: yang label topiknya cocok duluan, sisanya diisi acak.
function pickTestimonials(product, topics = [], count = TESTIMONI_PER_SEND, random = Math.random) {
  const list = ((FACTS[product] || {}).testimonials || []).map((t) => (typeof t === 'string' ? { url: t, tags: [] } : t));
  const wanted = topics.filter((t) => TESTIMONI_TOPICS[t]);
  const matches = shuffle(list.filter((t) => t.tags.some((tag) => wanted.includes(tag))), random);
  const rest = shuffle(list.filter((t) => !matches.includes(t)), random);
  return matches.concat(rest).slice(0, count).map((t) => t.url);
}

// Ambil teks balasan Claude, deteksi token handoff, rapikan format untuk WhatsApp.

const HANDOFF_TOKEN = '[HANDOFF]'; // bot dijeda sementara, CS manusia ambil alih
const INFO_TOKEN = '[INFO_ADMIN]'; // admin cukup dikabari, bot tetap lanjut jualan
const FALLBACK_REPLY =
  'Maaf kak, sistem kami lagi sibuk sebentar. Tim CS akan segera membalas chat kakak ya 🙏';

function toWhatsApp(text) {
  return text
    .replace(/\*\*(.+?)\*\*/g, '*$1*')
    .replace(/^#+\s*/gm, '')
    .trim();
}

function parseReply(response) {
  const block = response && Array.isArray(response.content)
    ? response.content.find((c) => c.type === 'text')
    : null;

  if (!block || !block.text) {
    const error = (response && response.error && response.error.message) || 'Respons Claude kosong';
    return { reply: FALLBACK_REPLY, needsHuman: true, apiError: error };
  }

  const needsHuman = block.text.includes(HANDOFF_TOKEN);
  const infoAdmin = block.text.includes(INFO_TOKEN);
  // [TESTIMONI] atau [TESTIMONI:flek,kusam]
  const testiMatch = block.text.match(/\[TESTIMONI(?::([a-z_,\s]+))?\]/i);
  const sendTestimoni = Boolean(testiMatch);
  const testimoniTopics = testiMatch && testiMatch[1]
    ? testiMatch[1].split(',').map((t) => t.trim().toLowerCase()).filter(Boolean)
    : [];
  const clean = [HANDOFF_TOKEN, INFO_TOKEN].reduce((t, tok) => t.split(tok).join(''), block.text)
    .replace(/\[TESTIMONI(?::[^\]]*)?\]/gi, '');
  // Balasan yang isinya hanya token testimoni tetap dijawab singkat, bukan pesan "sistem sibuk".
  const reply = toWhatsApp(clean) || (sendTestimoni ? 'Ini beberapa testimoni pembeli ya kak.' : '');
  return { reply: reply || FALLBACK_REPLY, needsHuman, infoAdmin, sendTestimoni, testimoniTopics, apiError: null };
}

const ctx = $('Siapkan Konteks').first().json;
const parsed = parseReply($input.first().json);
const order = $('Hasil Tool').isExecuted ? $('Hasil Tool').first().json.order : null;
const stored = $('Get row(s)').first().json || {};
const history = ctx.messages.concat([{ role: 'assistant', content: parsed.reply }]);
return [{
  json: {
    phone: ctx.phone,
    name: ctx.name,
    incoming: ctx.incoming,
    active_product: ctx.active_product,
    ref: ctx.ref,
    isClosing: ctx.isClosing,
    needsHuman: parsed.needsHuman,
    infoAdmin: parsed.infoAdmin,
    testimoni: parsed.sendTestimoni ? pickTestimonials(ctx.active_product, parsed.testimoniTopics) : [],
    // Error API (bukan permintaan lead) cukup dinotif, bot tidak dijeda.
    pauseBot: parsed.needsHuman && !parsed.apiError,
    apiError: parsed.apiError,
    reply: parsed.reply,
    history: JSON.stringify(history),
    order,
    orderText: order ? order.orderId + ' (' + (order.method === 'cod' ? 'COD' : 'Transfer') + ', Rp' + order.total.toLocaleString('id-ID') + ')' : '',
    last_order_id: order ? order.orderId : (stored.last_order_id || ''),
    last_order_at: order ? new Date().toISOString() : (stored.last_order_at || ''),
    first_chat_at: stored.first_chat_at || new Date().toISOString(),
    last_chat_at: new Date().toISOString(),
    // Notif closing hanya saat order benar-benar dibuat di Scalev.
    notify: Boolean(order) || parsed.needsHuman || parsed.infoAdmin,
  },
}];

